import fs from 'node:fs/promises';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {prepare,fake,validate,phase,preflightPhase,sha,entries,durable} from '../support/lw-real-runner.mjs';
export async function run(root,name,releaseFile,releaseSha,options={}){const m=await validate(root,releaseFile,releaseSha);await preflightPhase(root,name,options);if(name==='save'&&!options.selection)throw Error('Explicit reviewed selection is required');const release=JSON.parse(await fs.readFile(releaseFile,'utf8'));const {loadLlmConfig}=await import('../../services/llm/config.ts');const {OpenAiCompatibleProvider}=await import('../../services/llm/provider.ts');const config=await loadLlmConfig({filePath:release.configFile});if(config.model!==release.expectedModel||sha(config.baseUrl)!==release.expectedEndpointSha)throw Error('Configured Provider identity mismatch');await durable(path.join(root,'config-read-'+Date.now()+'.json'),{configReads:1,model:config.model,endpointSha:sha(config.baseUrl)});const result=await phase(root,name,new OpenAiCompatibleProvider(config),options);return {configReads:1,model:config.model,endpointSha:sha(config.baseUrl),ledgerCalls:(await entries(m.ledger)).length,result};}
if(process.argv[1]&&path.resolve(process.argv[1])===fileURLToPath(import.meta.url)){const [mode,root,name,release,releaseSha,...flags]=process.argv.slice(2);let result;if(mode==='prepare')result=await prepare(root);else if(mode==='fake')result=await fake(root);else if(mode==='run'){const at=flags.indexOf('--selection');const selection=at>=0?JSON.parse(await fs.readFile(flags[at+1],'utf8')):undefined;result=await run(root,name,release,releaseSha,{continueExplicit:flags.includes('--continue'),selection});}else throw Error('prepare [TEMP-root] | fake [fresh-TEMP-root] | run root extract|qa|save|requery|no_evidence release.json releaseSHA [--continue] [--selection preview.json]');console.log(JSON.stringify(result,null,2));if(mode==='run'&&((result.result?.job&&result.result.job.status!=='completed')||result.result?.status==='failed'))process.exitCode=1;}
